#!/usr/bin/env bash
set -euo pipefail

SRC="/workspaces/Photon-Camera-fresh-iris"
OUT="$SRC/fresh_iris_outputs"
BRANCH="experimental-clean-photon-rebuild"
HEAD_SHORT="aac8ea5a"
STAMP="$(date +%Y%m%d_%H%M%S)"

fail() { echo "FAIL: $*" >&2; exit 1; }
sha() { sha256sum "$1" | awk '{print toupper($1)}'; }

cd "$SRC" || fail "Missing active Codespace"
mkdir -p "$OUT"
[[ -f local.properties ]] || fail "local.properties missing"

DINIT="app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl"
DACC="app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl"
RENDERJ="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java"
RENDERG="app/src/main/assets/shaders/motionv2/render.glsl"
GAINMAP="app/src/main/assets/shaders/motionv2/gainmap.glsl"
VERSION="app/version.properties"
COLORJ="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2ColorTransform.java"
DENOISEJ="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Denoise.java"
COLORG="app/src/main/assets/shaders/motionv2/color_transform.glsl"
DENOISEG="app/src/main/assets/shaders/motionv2/denoise.glsl"
RECON="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java"
ALIGN="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Alignment.java"
INPUT="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java"
HDRX="app/src/main/java/com/particlesdevs/photoncamera/processing/processor/HdrxProcessor.java"
POST="app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/PostPipeline.java"
UHDR="app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2UltraHdr.java"

declare -A CUR
CUR['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']='E9F9C7EB0692B47D8BC00DEE2A24D7776B7C2A1C83AB3FF3B41FB5C99E14B97E'
CUR['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='9E2643D9AD35BF632E328D33E467BE84F7C5C902BC7F3C3C8A39B95D6F8D903C'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']='C09A2BF605DA61B0629AC6B6F83C03FAEAF30B144A4DB3EA7A9B4644596DF709'
CUR['app/src/main/assets/shaders/motionv2/render.glsl']='BC29D7B12B1E57BEC4EAB2FED28F61853E65A9352D2B6CD965879B92A598EACA'
CUR['app/src/main/assets/shaders/motionv2/gainmap.glsl']='7B562A9B2F8445374F0349069802B16602B46E6E60CCEC4F59E24F17CDB8DC45'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/ultrahdr/MotionV2UltraHdr.java']='197BA5A0FC77B11D98BA0667C083A105214736A709AB0D1CD7361FF3F35727B9'
CUR['app/version.properties']='10323A44E9DF0DF8D34744E729D853FA5440A5A1AAA1C7D8962948E4DF274C0B'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2ColorTransform.java']='FA08A31B10C4801BF12C76BD2AE9371ED920CC08AD6C7A5F781BB7F9219781A2'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Denoise.java']='E36C9CF5BE696A6B9F20DB1DA8585283EF72FB34D4A55D85233D3987F57DEE9B'
CUR['app/src/main/assets/shaders/motionv2/color_transform.glsl']='7568832F32C701D7E1F2D7F56E5B5BE7C8A8CF2B46D307478322E1824DE8AFFF'
CUR['app/src/main/assets/shaders/motionv2/denoise.glsl']='3C4BB26080FD50DFEF4656A03F7EFC6171A1F791E77EDF0A36863AECE299720E'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2CfaReconstruction.java']='76CAC4E7FE2B185068ADE3F34D5BB04FA60E81FFF3E05D3027897501A9764874'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/processor/MotionV2Alignment.java']='80548631423555C5C104A76E5B5950FFB44C69008D85D47440C8E01D7A0B2BA8'
CUR['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2CfaInput.java']='C3699054F6A25308576618754A2B5317AD387DD0E8A424435779934E0EE968F2'
declare -A PAYLOAD
PAYLOAD['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']=''
PAYLOAD['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']=''
PAYLOAD['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']=''
PAYLOAD['app/src/main/assets/shaders/motionv2/render.glsl']=''
PAYLOAD['app/src/main/assets/shaders/motionv2/gainmap.glsl']=''
PAYLOAD['app/version.properties']='I1dlZCBBdWcgMDUgMjI6NTY6MDQgRURUIDIwMjYKVkVSU0lPTl9OQU1FPTAuOTcyNjQzNApWRVJTSU9OX0JVSUxEPTI2NDM0Cg=='
declare -A NEWHASH
NEWHASH['app/src/main/assets/shaders/motionv2/direct_rgb_init.glsl']='8E0D3A176280C49D17094BC318382F9C1AF97C76FFFA85ACA7B19053F516C5C1'
NEWHASH['app/src/main/assets/shaders/motionv2/direct_rgb_accumulate.glsl']='01917E32EBD3DCAA11AE701A51BBC1743A634CD03EBC4C7B3BE68AA3FAA17611'
NEWHASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java']='94429147908FB789575B8C38D681C7C000415E088ACDADF448F1F24CE68921E4'
NEWHASH['app/src/main/assets/shaders/motionv2/render.glsl']='DA09F020A5D3786B6EA55616A3044DFB1A152C1A805A34A0791249C1F6A4E34D'
NEWHASH['app/src/main/assets/shaders/motionv2/gainmap.glsl']='9D5F8141F6C81A8AF698FD0FCD309567D75FD8C5735E75203806C23D2F905E89'
NEWHASH['app/version.properties']='EFD066DDE350D4C5B506F14FA7280889304934FD18B1933BF2D2557BAB3EEA5C'

echo "======================================================================"
echo "26434 - 26430 STABLE BASE + SMOOTH MOTION TRUST + TRUE ULTRA HDR"
echo "======================================================================"

echo "=== GATE 0: EXACT 26433 LINEAGE + PROTECTED BEHAVIOR ==="
[[ "$(git branch --show-current)" == "$BRANCH" ]] || fail "Wrong branch"
[[ "$(git rev-parse --short=8 HEAD)" == "$HEAD_SHORT" ]] || fail "Unexpected committed HEAD"

for rel in "${!CUR[@]}"; do
  [[ -f "$rel" ]] || fail "Missing current lineage file: $rel"
  [[ "$(sha "$rel")" == "${CUR[$rel]}" ]] || fail "Current 26433 hash mismatch: $rel"
done

grep -q '^VERSION_NAME=0\.9726433$' "$VERSION" || fail "Not on 26433 worktree"
grep -q '^VERSION_BUILD=26433$' "$VERSION" || fail "Not on build 26433"

# All requested frames stay eligible.
grep -q 'IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF' "$HDRX" || fail "All-frame Motion handoff missing"
grep -q 'targetFraction=1.0' "$HDRX" || fail "All-frame target missing"
grep -q 'globalGyroDiscard=false' "$HDRX" || fail "Global Motion discard returned"

# Old Photon graph still isolated.
grep -q 'exposureFusion=false esd=false ablc=false' "$POST" || fail "Legacy V2 bypass missing"
grep -q 'initial=false autoExposure=false' "$POST" || fail "Legacy tone bypass missing"
grep -q 'captureSharpening=false correctingFlow=false sharpen2=false' "$POST" || fail "Legacy sharpening bypass missing"

# 26433 bad support architecture must be present now so we can prove it is removed.
grep -q 'IRIS_26432_STACK_SIZE_INVARIANT_REFERENCE_ROBUSTNESS' "$DACC" || fail "Expected 26433 bad support baseline missing"
grep -q 'referenceCeiling=referenceAnchor\*1.70' "$DACC" || fail "Expected hard reference ceiling missing"
grep -q 'perFrameCap=mix(0.72,0.11,edgeStrength)' "$DACC" || fail "Expected hard per-frame cap missing"

# User-liked color/lens shading and minimal denoise are immutable in this build.
grep -q 'IRIS_26431_MOTION_V2_COLOR_AND_LENS_SHADING_OWNER' "$COLORJ" || fail "26431 color owner missing"
grep -q 'IRIS_26431_MINIMAL_SUPPORT_OWNED_RESIDUAL_CLEANUP' "$DENOISEG" || fail "26431 minimal denoise missing"

echo "PASS: exact current regression + desired retained behavior proven"

echo "=== GATE 1: BACKUP BRANCH + PRE-EDIT PATCH ==="
SAFETY="$OUT/safety_26434_stable_base_smooth_motion_ultrahdr_$STAMP"
CAND="$SAFETY/candidate"
mkdir -p "$CAND"
BACKUP="backup/codespace-before-26434-stable-base-smooth-motion-ultrahdr-$STAMP"
git branch "$BACKUP"
git diff --binary HEAD -- app > "$SAFETY/pre_26434_working_tree.patch"

TARGETS=("$DINIT" "$DACC" "$RENDERJ" "$RENDERG" "$GAINMAP" "$VERSION")
PROTECTED_BEFORE="$SAFETY/protected_before.txt"
PROTECTED_AFTER="$SAFETY/protected_after.txt"

hash_protected() {
  local out="$1"
  : > "$out"
  while IFS= read -r -d '' f; do
    skip=0
    for t in "${TARGETS[@]}"; do [[ "$f" == "$t" ]] && skip=1 && break; done
    [[ "$skip" -eq 1 ]] && continue
    printf '%s  %s\n' "$(sha "$f")" "$f" >> "$out"
  done < <(git ls-files -z app)
  sort -o "$out" "$out"
}
hash_protected "$PROTECTED_BEFORE"

echo "=== GATE 2: TEMPORARY COMPLETE CANDIDATES ==="
for rel in "${!PAYLOAD[@]}"; do
  dst="$CAND/$rel"
  mkdir -p "$(dirname "$dst")"
  printf '%s' "${PAYLOAD[$rel]}" | base64 -d > "$dst"
  [[ "$(sha "$dst")" == "${NEWHASH[$rel]}" ]] || fail "Candidate hash mismatch: $rel"
done

CI="$CAND/$DINIT"
CA="$CAND/$DACC"
CRJ="$CAND/$RENDERJ"
CRG="$CAND/$RENDERG"
CG="$CAND/$GAINMAP"
CV="$CAND/$VERSION"

echo "=== GATE 2A: CROSS-BUILD BEHAVIOR PROOF ==="
# Restore exact 26429/26430 stable support carrier.
[[ "$(sha "$CI")" == "8E0D3A176280C49D17094BC318382F9C1AF97C76FFFA85ACA7B19053F516C5C1" ]] ||   fail "26429 initializer not restored"

# No bad 26432/33 hard support mechanics.
! grep -q 'referenceCeiling' "$CA" || fail "Hard reference support ceiling survived"
! grep -q 'perFrameCap' "$CA" || fail "Hard per-frame cap survived"
! grep -q 'referenceAnchor' "$CA" || fail "Weakest-channel reference anchor survived"

# Smooth shared RGB trust + motion/occlusion detection.
grep -q 'IRIS_26434_SMOOTH_SHARED_TEMPORAL_TRUST' "$CA" || fail "26434 trust marker missing"
grep -q 'patchAgreement' "$CA" || fail "Reference patch motion detector missing"
grep -q 'flowContinuity' "$CA" || fail "Flow discontinuity detector missing"
grep -q 'float sharedTrust=' "$CA" || fail "Shared CFA trust missing"
grep -q 'spatial\*sharedTrust\*saturation' "$CA" || fail "Shared trust not used uniformly"
! grep -q 'cur\.r' "$CA" || fail "Evolving RGB feedback returned"

# Exact 26430 SDR highlight algorithm, with ONLY requested 0.80 scale added.
grep -q 'IRIS_26434_26430_HEADROOM_BASE_MINUS_032EV' "$CRG" || fail "26430 render base marker missing"
grep -q 'const float start=0.50;' "$CRG" || fail "26430 headroom start changed"
grep -q 'const float logShape=6.0;' "$CRG" || fail "26430 highlight shape changed"
grep -q 'linearSrgb\*=outputExposureScale;' "$CRG" || fail "0.80 output scale missing"
grep -q 'OUTPUT_EXPOSURE_SCALE = 0.80f' "$CRJ" || fail "Requested exposure scale missing"

# Ultra HDR: smooth, highlight-only, no blanket exposure lift.
grep -q 'IRIS_26434_SMOOTH_HIGHLIGHT_ONLY_TRUE_V2_GAINMAP' "$CG" || fail "Smooth V2 gainmap missing"
grep -q 'localHdrY' "$CG" || fail "Spatial HDR averaging missing"
grep -q 'localSdrY' "$CG" || fail "Spatial SDR averaging missing"
grep -q 'highlightAuthority=smoothstep(1.08,1.30,hdrY)' "$CG" || fail "Highlight-only gain gate missing"
grep -q 'float ratio=mix(1.0,physicalRatio,highlightAuthority)' "$CG" || fail "Unity body gain missing"
grep -q 'Math.min(' "$CRJ" || fail "Gain ratio bound missing"
grep -Fq 'Math.min(4.0f, OUTPUT_EXPOSURE_SCALE * canonicalSensorWhite)' "$CRJ" || fail "Exact conservative 4x gain cap missing"
! grep -Fq 'Math.min(8.0f, OUTPUT_EXPOSURE_SCALE * canonicalSensorWhite)' "$CRJ" || fail "Old 8x Ultra HDR gain cap survived"

grep -q '^VERSION_NAME=0\.9726434$' "$CV" || fail "Candidate version wrong"
grep -q '^VERSION_BUILD=26434$' "$CV" || fail "Candidate build wrong"

echo "candidate/source validation PASS"

echo "=== GATE 3: GLSL REAL COMPILER VALIDATION ==="
command -v glslangValidator >/dev/null 2>&1 || fail "glslangValidator missing"
WRAPC="$SAFETY/wrap_compute.py"
WRAPF="$SAFETY/wrap_frag.py"
cat > "$WRAPC" <<'PY'
from pathlib import Path
import re,sys
s=Path(sys.argv[1]).read_text()
s=re.sub(r'(?m)^#define\s+LAYOUT\s+//\s*\nLAYOUT\s*\n','',s,count=1)
Path(sys.argv[2]).write_text('#version 310 es\nlayout(local_size_x=8, local_size_y=8, local_size_z=1) in;\n'+s)
PY
cat > "$WRAPF" <<'PY'
from pathlib import Path
import sys
Path(sys.argv[2]).write_text('#version 310 es\n'+Path(sys.argv[1]).read_text())
PY

python3 "$WRAPC" "$CI" "$SAFETY/init.comp"
python3 "$WRAPC" "$CA" "$SAFETY/acc.comp"
python3 "$WRAPF" "$CRG" "$SAFETY/render.frag"
python3 "$WRAPF" "$CG" "$SAFETY/gain.frag"
python3 "$WRAPF" "$COLORG" "$SAFETY/color.frag"
python3 "$WRAPF" "$DENOISEG" "$SAFETY/denoise.frag"

GLSLLOG="$SAFETY/glslang_26434.txt"
{
  glslangValidator -S comp "$SAFETY/init.comp"
  glslangValidator -S comp "$SAFETY/acc.comp"
  glslangValidator -S frag "$SAFETY/render.frag"
  glslangValidator -S frag "$SAFETY/gain.frag"
  glslangValidator -S frag "$SAFETY/color.frag"
  glslangValidator -S frag "$SAFETY/denoise.frag"
} 2>&1 | tee "$GLSLLOG"

echo "Temporary-copy validation: PASS"

echo "=== GATE 4: APPLY EXACT CANDIDATES ==="
for rel in "${!PAYLOAD[@]}"; do
  mkdir -p "$(dirname "$rel")"
  cp "$CAND/$rel" "$rel"
done

hash_protected "$PROTECTED_AFTER"
cmp -s "$PROTECTED_BEFORE" "$PROTECTED_AFTER" || fail "Protected tracked app source changed"

# Re-prove immutable color/denoise/reconstruction/alignment after actual edit.
[[ "$(sha "$COLORJ")" == "${CUR[$COLORJ]}" ]] || fail "26431 color Java changed"
[[ "$(sha "$COLORG")" == "${CUR[$COLORG]}" ]] || fail "26431 color shader changed"
[[ "$(sha "$DENOISEJ")" == "${CUR[$DENOISEJ]}" ]] || fail "26431 denoise Java changed"
[[ "$(sha "$DENOISEG")" == "${CUR[$DENOISEG]}" ]] || fail "26431 denoise shader changed"
[[ "$(sha "$RECON")" == "${CUR[$RECON]}" ]] || fail "26429 reconstruction Java changed"
[[ "$(sha "$ALIGN")" == "${CUR[$ALIGN]}" ]] || fail "Alignment owner changed"
[[ "$(sha "$INPUT")" == "${CUR[$INPUT]}" ]] || fail "Direct input changed"
[[ "$(sha "$UHDR")" == "${CUR[$UHDR]}" ]] || fail "Working Ultra HDR attachment helper changed"

for rel in "${!NEWHASH[@]}"; do
  [[ "$(sha "$rel")" == "${NEWHASH[$rel]}" ]] || fail "Applied candidate differs: $rel"
done

git diff --check -- "${TARGETS[@]}"

echo "candidate/source validation PASS"
echo "Temporary-copy validation: PASS"
echo "PRE-BUILD SAFETY PROOF PASSED"

git diff --binary HEAD -- app > "$SAFETY/post_26434_working_tree.patch"

echo "=== GATE 5: JAVAC PROOF ==="
JLOG="$OUT/26434_JAVAC_PROOF_$STAMP.txt"
set +e
./gradlew :app:compileDebugJavaWithJavac --stacktrace 2>&1 | tee "$JLOG"
RC=${PIPESTATUS[0]}
set -e
[[ "$RC" -eq 0 ]] || fail "Javac failed; see $JLOG"
echo "JAVAC PROOF PASSED"

echo "=== GATE 6: BUILD 0.9726434 / 26434 ==="
BLOG="$OUT/build_26434_stable_base_smooth_motion_ultrahdr_$STAMP.txt"
set +e
./gradlew :app:assembleDebug --stacktrace 2>&1 | tee "$BLOG"
RC=${PIPESTATUS[0]}
set -e
[[ "$RC" -eq 0 ]] || fail "Gradle failed; see $BLOG"
grep -q 'BUILD SUCCESSFUL' "$BLOG" || fail "BUILD SUCCESSFUL not found"

APK_SRC="$(find app/build/outputs/apk -type f -name '*.apk' -printf '%T@ %p\n' | sort -nr | head -1 | cut -d' ' -f2-)"
[[ -n "$APK_SRC" && -f "$APK_SRC" ]] || fail "Built APK not found"
APK="$SRC/IrisCamera-0.9726434-26434-v2-stable-base-smooth-motion-ultrahdr-debug.apk"

find "$SRC" -maxdepth 1 -type f -name 'IrisCamera-*.apk' -delete
mv -f "$APK_SRC" "$APK"
find app/build -type f -name '*.apk' -delete

RESULT="$OUT/26434_RESULT_$STAMP.txt"
cat > "$RESULT" <<EOF
26434 STABLE BASE + SMOOTH MOTION TRUST + TRUE ULTRA HDR

Protected:
- 26431 color/lens-shading path byte-identical
- 26431 minimal residual denoise byte-identical
- 26429 reconstruction Java/alignment/input byte-identical
- all selected Motion frames remain eligible
- old Photon post graph remains bypassed

Removed:
- 26432/26433 hard reference-support ceiling
- 26432/26433 edge-dependent per-frame cap
- weakest-channel support anchor

New merge:
- exact 26429 normalized-convolution support behavior restored
- one shared R/G/B local trust scalar
- immutable reference 3x3 green patch agreement
- local flow-discontinuity motion/occlusion detection
- smooth Tukey rejection; bad local observations can reach zero
- no global frame discard; designed to scale to 15/20/30 frames

Rendering:
- exact 26430 SDR headroom mapping restored
- one requested 0.80 linear output scale (~-0.322 EV)

Ultra HDR:
- true pre-tone V2 extended-linear source
- same 0.80 scale as SDR/HDR target
- 5x5 smooth local luminance ratio
- unity body/midtone gain
- gain begins only above true HDR white
- conservative max gain ratio capped at 4x
- existing working Android Gainmap attachment path preserved

Backup: $BACKUP
Pre patch: $SAFETY/pre_26434_working_tree.patch
Post patch: $SAFETY/post_26434_working_tree.patch
GLSL proof: $GLSLLOG
Javac proof: $JLOG
Build log: $BLOG
APK: $APK

candidate/source validation PASS
Temporary-copy validation: PASS
PRE-BUILD SAFETY PROOF PASSED
JAVAC PROOF PASSED
BUILD SUCCESSFUL VERIFIED

No commit.
No push.
dev untouched.
local.properties protected.
EOF

echo "======================================================================"
echo "26434 BUILD SUCCESSFUL"
echo "APK: $APK"
echo "RESULT: $RESULT"
echo "No commit. No push. dev untouched."
echo "======================================================================"
